entries[106830] = { ["name"] = "Hauen", ["text"] = "50 Energie 8 Meter Reichweite\nSofort\nBenötigt Katzengestalt\nGreift alle gegnerischen Ziele innerhalb von 8 Metern an, fügt ihnen ( 1232 + 1 * Angriffskraft * 191 / 1000) Blutungsschaden zu sowie zusätzlich [5 * ( 1 + 1 * Angriffskraft * 141 / 1000)] Schaden im Verlauf von 15 Sek. Verursacht außerdem den Effekt 'Kampfesmüdigkeit'.\n\nKampfesmüdigkeit\nDemoralisiert das Ziel und verringert den von ihm verursachten körperlichen Schaden 30 Sek. lang um 10%." }
entries[106832] = { ["name"] = "Hauen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Katzengestalt, Bärengestalt\nGreift alle gegnerischen Ziele in der Nähe an, fügt ihnen direkten Schaden zu und lässt sie regelmäßigen Blutungsschaden erleiden. Verursacht außerdem den Effekt 'Kampfesmüdigkeit'. Der verursachte Schaden hängt von der Gestalt des Druiden ab.\n\nKampfesmüdigkeit\nDemoralisiert das Ziel und verringert den von ihm verursachten körperlichen Schaden 30 Sek. lang um 10%." }
