entries[108194] = { ["name"] = "Ersticken", ["text"] = "Ersetzt Strangulieren\n30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nLässt einen Gegner vom Boden abheben und würgt ihn mit dunkler Energie, wodurch das Ziel 5 Sek. lang betäubt wird. Funktioniert wie ein Stilleeffekt, wenn das Ziel gegen Betäubungseffekte immun ist.\n\nErsetzt 'Strangulieren'." }
