entries[108200] = { ["name"] = "Unbarmherziger Winter", ["text"] = "Sofort 1 min Abklingzeit\nUmgibt den Todesritter 8 Sek. lang mit einem Wirbelsturm eiskalter Luft, die Gegner innerhalb von 8 Metern alle 1 Sek. unterkühlt. Jeder Impuls verringert das Bewegungstempo der Ziele 3 Sek. lang um 15%. Dieser Effekt ist bis zu 5-mal stapelbar. Der fünfte Stapel betäubt das Ziel 6 Sek. lang." }
entries[108201] = { ["name"] = "Entweihter Boden", ["text"] = "Sofort 2 min Abklingzeit\nVerderbt 10 Sek. lang den Boden in einem Radius von 8 Metern zu Füßen des Todesritters. Während sich der Todesritter in dieser Verderbnis aufhält, ist er gegen Effekte immun, die zum Verlust der Kontrolle über den Charakter führen. Diese Fähigkeit hebt solche Effekte bei ihrer Auslösung auf." }
