entries[108208] = { ["name"] = "Trickbetrug", ["text"] = "Wenn Ihr aus der Verstohlenheit heraus Schaden verursacht oder in Verstohlenheit angegriffen werdet, endet ihr Effekt nicht sofort, sondern erst 3 Sek. später." }
