entries[108210] = { ["name"] = "Nervenlähmung", ["text"] = "Erfolgreicher Einsatz von 'Nierenhieb' oder 'Fieser Trick' verringert zusätzlich, nachdem der Effekt dieser Fähigkeiten abgelaufen ist, 6 Sek. lang den verursachten Schaden des Ziels um 50% (25% bei Spielercharakteren) sowie seine hervorgerufene Heilung um 10%." }
entries[108211] = { ["name"] = "Egelgift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem nicht-tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei Euren Nahkampfangriffen besteht eine Chance von 50%, den Gegner 10 Sek. lang zu vergiften. Durch alle folgenden Waffenangriffe gegen das vergiftete Ziel werdet Ihr um 10% des verursachten Schadens geheilt. [ Tückische Klinge : Effekt von 'Tückische Klinge':\nRegeneriert sofort 5% Eurer gesamten Gesundheit ](Procchance: 50%)" }
entries[108212] = { ["name"] = "Geschwindigkeitsschub", ["text"] = "15 Energie\nSofort\nErhöht Euer Bewegungstempo 0.50 Sek. lang um 1% und hebt sämtliche Bewegungseinschränkungseffekte auf. Bricht Verstohlenheit nicht ab." }
entries[108214] = { ["name"] = "Teufelsflammen" }
entries[108215] = { ["name"] = "Betäubendes Gift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem nicht-tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 20%, den Gegner zu vergiften. Das Gift wirkt 15 Sek. lang und ist bis zu 4-mal auf einem einzelnen Ziel stapelbar. Beim Erreichen des vierten Stapels wird der Betroffene 4 Sek. lang betäubt. [ Tückische Klinge : Effekt von 'Tückische Klinge':\nRuft eine sofortige Lähmung des Unterkörpers des Ziels hervor, wodurch es 4 Sek. lang bewegungsunfähig wird ](Procchance: 20%)" }
entries[108216] = { ["name"] = "Schmutzige Tricks", ["text"] = "Die Energiekosten Eurer Fähigkeiten 'Solarplexus' und 'Blenden' werden um 100% verringert und Ihr Effekt wird durch den von Euren Giften und Blutungseffekten verursachten Schaden nicht mehr unterbrochen." }
entries[108217] = { ["name"] = "Teufelsflammen", ["text"] = "Sofort\nDie Teufelsflammen pulsieren, verbrennen alle Feinde in der Nähe und verursachen so 11875 bis 13125 Feuerschaden." }
entries[108218] = { ["name"] = "Sengendes Blut", ["text"] = "30 Meter Reichweite\nSofort 3 sek. Abklingzeit\nBringt das Blut zufälliger Gegner, die sich weit entfernt befinden, zum Kochen. Mit fortschreitender Distanz zum Zaubernden erleidet das Ziel mehr Schaden." }
