entries[108269] = { ["name"] = "Totem der Energiespeicherung", ["text"] = "5% von Grundmana\nSofort 45 sek. Abklingzeit\nBeschwört ein Lufttotem mit [ Glyphe 'Totemische Lebenskraft' : 5% der Gesundheit des Zaubernden zu dessen Füßen / 5 Gesundheit zu Füßen des Zaubernden], das elektrische Energie aus der umgebenden Luft sammelt und dann nach [ Glyphe 'Totem der Energiespeicherung' : 3 / 5] Sek. explodiert, um alle Gegner innerhalb von 8 Metern 5 Sek. lang zu betäuben." }
entries[108270] = { ["name"] = "Totem des Steinbollwerks", ["text"] = "8% von Grundmana\nSofort 1 min Abklingzeit\nBeschwört für 30 Sek. ein Erdtotem mit [ Glyphe 'Totemische Lebenskraft' : 15 / 10]% der Gesundheit des Zaubernden zu dessen Füßen, das ihm einen Schild gewährt, der 10 Sek. lang (Zaubermacht * 0.875 * 4) Schaden absorbiert und anschließend alle 5 Sek. zusätzlich bis zu (Zaubermacht * 0.875) Schaden absorbiert." }
entries[108271] = { ["name"] = "Astralverschiebung", ["text"] = "Sofort 1.5 min Abklingzeit\nSucht Schutz durch eine teilweise Verschiebung auf die Elementarebenen und verringert den erlittenen Schaden 6 Sek. lang um 40%." }
entries[108272] = { ["name"] = "Verbesserter Geisterwolf", ["text"] = "In Geisterwolfgestalt ignoriert Ihr Verlangsamungseffekte.\nModifies Effect #3's Value +100:\nGeisterwolf" }
entries[108273] = { ["name"] = "Totem des Windwandelns", ["text"] = "6% von Grundmana\nSofort 1 min Abklingzeit\nBeschwört ein Lufttotem mit [ Glyphe 'Totemische Lebenskraft' : 5% der Gesundheit des Zaubernden zu dessen Füßen / 5 Gesundheit zu Füßen des Zaubernden], das 6 Sek. lang Schlachtzugsmitgliedern im Umkreis von 40 Metern Immunität gegenüber bewegungseinschränkenden Effekten gewährt." }
entries[108277] = { ["name"] = "Sha-Heimsuchung beschwören" }
entries[108279] = { ["name"] = "Totem des ruhigen Gemüts", ["text"] = "6% von Grundmana\nSofort 1 min Abklingzeit\nBeschwört 6 Sek. lang ein Lufttotem mit 5 Gesundheit zu Füßen des Zaubernden, das Schlachtzugsmitgliedern im Umkreis von 30 Metern Immunität gegenüber Zauberunterbrechungen und Stilleeffekten gewährt." }
entries[108280] = { ["name"] = "Totem der Heilungsflut", ["text"] = "8% von Grundmana\nSofort 3 min Abklingzeit\nBeschwört ein Wassertotem mit [ Glyphe 'Totemische Lebenskraft' : 15 / 10]% der Gesundheit des Zaubernden zu dessen Füßen, das 10 Sek. anhält. Das Totem der Heilungsflut pulsiert alle 2 Sek. und heilt die 5 (12 in 25 - Spieler - Instanzen) am schwersten verletzten Gruppen- oder Schlachtzugsmitglieder im Umkreis von 40 Metern um 4932 ." }
entries[108281] = { ["name"] = "Führung der Ahnen", ["text"] = "Sofort 2 min Abklingzeit\nWenn Ihr im Verlauf der nächsten 10 Sek. direkten Schaden verursacht oder direkte Heilung hervorruft, werden 60% der Heilung oder 40% des verursachten Schadens als Heilung auf bis zu 3 verletzte Gruppen- oder Schlachtzugsmitglieder in der Nähe übertragen." }
entries[108282] = { ["name"] = "Leitfähigkeit", ["text"] = "Wenn Ihr 'Welle der Heilung', 'Große Welle der Heilung', 'Heilende Woge' oder 'Kettenheilung' einsetzt, wird die Dauer Eures Zaubers 'Heilender Regen' um 4.00 Sek. erhöht.\n\nWenn Ihr 'Blitzschlag', 'Kettenblitzschlag' [ Elementarschlag : 'Elementarschlag' ]'Erdschock' oder 'Sturmschlag' einsetzt, wird die Dauer Eures Zaubers 'Heilender Regen' um 4.00 Sek. erhöht.\n\nDie Dauer von 'Heilender Regen' kann hierdurch nicht über 40 Sek. hinaus erhöht werden." }
entries[108283] = { ["name"] = "Echo der Elemente", ["text"] = "Wenn einer Eurer Zauber direkten Schaden verursacht oder direkte Heilung hervorruft, besteht eine Chance, dass Ihr den Effekt 'Echo der Elemente' erhaltet, wodurch der Effekt dieses Zaubers dupliziert wird.\n(100ms Abklingzeit)" }
entries[108284] = { ["name"] = "Beständige Totems", ["text"] = "Beim Beschwören eines zweiten Totems desselben Elements wird das erste Totem nicht mehr entfernt.\n\nEs kann immer nur ein Totem von diesem Effekt profitieren. Wirkt sich nicht auf Feuertotems aus." }
entries[108285] = { ["name"] = "Ruf der Elemente", ["text"] = "Sofort 3 min Abklingzeit\nBei Aktivierung wird die Abklingzeit aller Totems mit einer Basisabklingzeit unter 3 Minuten sofort abgeschlossen." }
entries[108287] = { ["name"] = "Totemische Projektion", ["text"] = "40 Meter Reichweite\nSofort 10 sek. Abklingzeit\nVerlegt Eure aktiven Totems an den angegebenen Ort." }
entries[108288] = { ["name"] = "Herz der Wildnis", ["text"] = "Sofort 6 min Abklingzeit\nWächter ( Hotfix - Passivfähigkeit )\nErhöht Beweglichkeit, Ausdauer und Intelligenz um 6%.\n\nWenn diese Fähigkeit ausgelöst wird, erhöht sie 45 Sek. lang die hervorgerufene Heilung und die Fähigkeiten des Druiden in seinen Kampfrollen außerhalb der Spezialisierung. Außerhalb von Arenen und Schlachtfeldern entfernt das Gestaltwandeln in die Bärengestalt 'Herz der Wildnis', und wenn der Druide kürzlich nicht in Bärengestalt war, werden für jede Sekunde außerhalb der Bärengestalt 4 Sek. der Abklingzeit zurückerstattet.\n\nGewährt den jeweiligen Rollen die folgenden Boni:\n\nAlle außer Wächter\nErhöht in Bärengestalt Beweglichkeit, Waffenkunde, Trefferchance sowie Rüstung. Gewährt Rache und verringert die Chance, kritische Nahkampftreffer zu erleiden.\n\nAlle außer Wildheit\nErhöht in Katzengestalt Beweglichkeit, Waffenkunde und Trefferchance.\n\nAlle außer Wiederherstellung\nVerringert die Manakosten aller Heilzauber um 100%. Wächterdruiden können außerdem 'Verjüngung' wirken, während sie sich in Tiergestalt befinden.\n\nAlle außer Gleichgewicht\nErhöht Zauberschaden und Trefferchance und verringert die Manakosten aller Schadenszauber um 100%.\n\nGleichgewicht, Wildheit, Wiederherstellung\nErhöht Beweglichkeit, Ausdauer und Intelligenz um 6%.\n\nWenn diese Fähigkeit ausgelöst wird, erhöht sie 45 Sek. lang die hervorgerufene Heilung und die Fähigkeiten des Druiden in seinen Kampfrollen außerhalb der Spezialisierung. [ Wächter : Außerhalb von Arenen und Schlachtfeldern entfernt das Gestaltwandeln in die Bärengestalt 'Herz der Wildnis', und wenn der Druide kürzlich nicht in Bärengestalt war, werden für jede Sekunde außerhalb der Bärengestalt 4 Sek. der Abklingzeit zurückerstattet ]\nGewährt den jeweiligen Rollen die folgenden Boni:\n\nAlle außer Wächter\nErhöht in Bärengestalt Beweglichkeit, Waffenkunde, Trefferchance sowie Rüstung. Gewährt Rache und verringert die Chance, kritische Nahkampftreffer zu erleiden.\n\nAlle außer Wildheit\nErhöht in Katzengestalt Beweglichkeit, Waffenkunde und Trefferchance.\n\nAlle außer Wiederherstellung\nVerringert die Manakosten aller Heilzauber um 100%. Wächterdruiden können außerdem 'Verjüngung' wirken, während sie sich in Tiergestalt befinden.\n\nAlle außer Gleichgewicht\nErhöht Zauberschaden und Trefferchance und verringert die Manakosten aller Schadenszauber um 100%." }
entries[108291] = { ["name"] = "Herz der Wildnis", ["text"] = "Sofort 6 min Abklingzeit\nErhöht Beweglichkeit, Ausdauer und Intelligenz dauerhaft um 6%. Wenn diese Fähigkeit ausgelöst wird, erhöht sie 45 Sek. lang die Fähigkeiten des Druiden in seinen Kampfrollen außerhalb der Gleichgewichtsspezialisierung. Gewährt den jeweiligen Rollen die folgenden Boni:\n\nWächter\nIn Bärengestalt werden Beweglichkeit, Waffenkunde, Trefferchance sowie Rüstung erhöht, es wird Rache gewährt und die Chance, kritische Nahkampftreffer zu erleiden, wird verringert.\n\nWildheit\nIn Katzengestalt werden Beweglichkeit, Waffenkunde und Trefferchance erhöht.\n\nWiederherstellung\nHeilung erhöht und Manakosten aller Heilzauber um 100% verringert." }
entries[108292] = { ["name"] = "Herz der Wildnis", ["text"] = "Sofort 6 min Abklingzeit\nErhöht Beweglichkeit, Ausdauer und Intelligenz dauerhaft um 6%. Wenn diese Fähigkeit ausgelöst wird, erhöht sie 45 Sek. lang die Fähigkeiten des Druiden in seinen Kampfrollen außerhalb der Wildheitsspezialisierung. Gewährt den jeweiligen Rollen die folgenden Boni:\n\nWächter\nIn Bärengestalt werden Beweglichkeit, Waffenkunde, Trefferchance sowie Rüstung erhöht, es wird Rache gewährt und die Chance, kritische Nahkampftreffer zu erleiden, wird verringert.\n\nWiederherstellung\nHeilung erhöht und Manakosten aller Heilzauber um 100% verringert.\n\nGleichgewicht\nZauberschaden und Trefferchance erhöht und Manakosten aller Schadenszauber um 100% verringert." }
entries[108293] = { ["name"] = "Herz der Wildnis", ["text"] = "Sofort 6 min Abklingzeit\nErhöht Beweglichkeit, Ausdauer und Intelligenz dauerhaft um 6%.\n\nWenn diese Fähigkeit ausgelöst wird, erhöht sie 45 Sek. lang die Fähigkeiten des Druiden in seinen Kampfrollen außerhalb der Wächterspezialisierung. Außerhalb von Arenen und Schlachtfeldern entfernt das Gestaltwandeln in die Bärengestalt 'Herz der Wildnis', und wenn der Druide in den letzten 3 Sek. nicht in Bärengestalt war, werden für jede Sekunde außerhalb der Bärengestalt 4 Sek. der Abklingzeit zurückerstattet.\n\nGewährt den jeweiligen Rollen die folgenden Boni:\n\nWildheit\nIn Katzengestalt werden Beweglichkeit, Waffenkunde und Trefferchance erhöht.\n\nWiederherstellung\nHeilung erhöht und Manakosten aller Heilzauber um 100% verringert. Gestattet es, 'Verjüngung' in Tiergestalt zu wirken.\n\nGleichgewicht\nZauberschaden und Trefferchance erhöht und Manakosten aller Schadenszauber um 100% verringert." }
entries[108294] = { ["name"] = "Herz der Wildnis", ["text"] = "Sofort 6 min Abklingzeit\nErhöht Beweglichkeit, Ausdauer und Intelligenz dauerhaft um 6%. Wenn diese Fähigkeit ausgelöst wird, erhöht sie 45 Sek. lang die hervorgerufene Heilung um 25% und verbessert die Fähigkeiten des Druiden in seinen Kampfrollen außerhalb der Wiederherstellungsspezialisierung. Gewährt den jeweiligen Rollen die folgenden Boni:\n\nWächter\nErhöht in Bärengestalt Beweglichkeit, Waffenkunde, Trefferchance sowie Rüstung, gewährt Rache und verringert die Chance, kritische Nahkampftreffer zu erleiden.\n\nWildheit\nErhöht in Katzengestalt Beweglichkeit, Waffenkunde und Trefferchance.\n\nGleichgewicht\nErhöht Zauberschaden und Trefferchance und verringert die Manakosten aller Schadenszauber um 100%." }
