entries[108366] = { ["name"] = "Seele entziehen", ["text"] = "Unbegrenzte Reichweite\nSofort\nEure Zauber [ Gebrechen : 'Bösartiger Griff', 'Seelendieb', 'Teufelsflamme' und 'Heimsuchung' ] [ Dämonologie : 'Schattenblitz', 'Seelenfeuer', 'Teufelsflamme' und 'Berührung des Chaos' ] [ Zerstörung : 'Verbrennen', 'Teufelsflamme', 'Schattenbrand' und 'Chaosblitz' ] gewähren sowohl Euch als auch Eurem Diener einen schattenhaften Schild, der 15 Sek. lang Schaden in Höhe [ Gebrechen : von 20% ] [ Dämonologie, Zerstörung : von 10% ] Eures verursachten Schadens absorbiert." }
entries[108370] = { ["name"] = "Seele entziehen", ["text"] = "Eure Zauber [ Gebrechen : 'Bösartiger Griff', 'Seelendieb', 'Teufelsflamme' und 'Heimsuchung' ] [ Dämonologie : 'Schattenblitz', 'Seelenfeuer', 'Teufelsflamme' und 'Berührung des Chaos' ] [ Zerstörung : 'Verbrennen', 'Teufelsflamme', 'Schattenbrand' und 'Chaosblitz' ] gewähren sowohl Euch als auch Eurem Diener einen schattenhaften Schild, der 15 Sek. lang Schaden in Höhe [ Gebrechen : von 20% ] [ Dämonologie, Zerstörung : von 10% ] Eures verursachten Schadens absorbiert." }
entries[108371] = { ["name"] = "Leben ernten", ["text"] = "40 Meter Reichweite\nErhöht den Schaden Eures Zaubers 'Blutsauger' um 50%. Erhöht die Heilung Eures Zaubers 'Blutsauger' um 150%." }
entries[108373] = { ["name"] = "Traum des Cenarius", ["text"] = "Wächter ( Hotfix - Passivfähigkeit )\nDer Smaragdgrüne Traum gewährt Euch abhängig von Eurer Spezialisierung einen Bonus.\n\nGleichgewicht\nErhöht die Heilung von 'Heilende Berührung' um 20%. 'Heilende Berührung' erhöht den Schadensbonus Eurer nächsten Finsternis um 35%.\n\nWildheit\nErhöht die Heilung von 'Heilende Berührung' um 20%. 'Heilende Berührung' erhöht den Schaden Eurer nächsten zwei Nahkampffähigkeiten um 40%.\n\nWächter\nErhöht die Heilung von 'Heilende Berührung' um 20% und die kritische Trefferchance von 'Zerfleischen (Bär)' um 10%. In Bärengestalt haben kritische Treffer von 'Zerfleischen' eine Chance von 50%, das nächste Wirken von 'Heilende Berührung' oder 'Wiedergeburt' zu einem kostenlosen Spontanzauber zu machen, der in allen Gestalten einsetzbar ist. Die Heilung von 'Heilende Berührung' hängt dabei von Eurer Angriffskraft ab, nicht von Eurer Zaubermacht.\n\nWiederherstellung\nErhöht den Schaden von 'Zorn' um 20% und heilt einen nahen Verbündeten um 100% des verursachten Schadens.\n\nGleichgewicht, Wildheit, Wiederherstellung\nDer Smaragdgrüne Traum gewährt Euch abhängig von Eurer Spezialisierung einen Bonus.\n\nGleichgewicht\nErhöht die Heilung von 'Heilende Berührung' um 20%. 'Heilende Berührung' erhöht den Schadensbonus Eurer nächsten Finsternis um 25%.\n\nWildheit\nErhöht die Heilung von 'Heilende Berührung' um 20%. 'Heilende Berührung' erhöht den Schaden Eurer nächsten zwei Nahkampffähigkeiten um 30%.\n\nWächter\nErhöht die Heilung von 'Heilende Berührung' um 20% und die kritische Trefferchance von 'Zerfleischen (Bär)' um 10%. In Bärengestalt haben kritische Treffer von 'Zerfleischen' eine Chance von 40%, das nächste Wirken von 'Heilende Berührung' oder 'Wiedergeburt' zu einem kostenlosen Spontanzauber zu machen, der in allen Gestalten einsetzbar ist. Die Heilung von 'Heilende Berührung' hängt dabei von Eurer Angriffskraft ab, nicht von Eurer Zaubermacht.\n\nWiederherstellung\nErhöht den Schaden von 'Zorn' um 20% und heilt einen nahen Verbündeten um 100% des verursachten Schadens." }
entries[108374] = { ["name"] = "Totem des aufsteigenden Feuers", ["text"] = "60 Meter Reichweite\nWirken in 1 sek.\nBeschwört ein Totem des Feuers, das regelmäßig den Schaden und die maximale Gesundheit naher Spielercharaktere erhöht. Das Totem hält 20 Sek. lang an, der Effekt ist bis zu 0-mal stapelbar." }
