entries[108409] = { ["name"] = "Stunde des Zwielichts", ["text"] = "Sofort\nWenn ein Schaden verursachender Angriff Eure Gesundheit unter 20% Eurer maximalen Gesundheit senkt, wird Euer gesamter erlittener Schaden 10 Sek. lang um 50% verringert.\n\nDieser Effekt kann nur ein Mal alle 90 Sek. auftreten." }
entries[108410] = { ["name"] = "Stunde des Zwielichts", ["text"] = "Wenn ein Schaden verursachender Angriff Eure Gesundheit unter 30% Eurer maximalen Gesundheit senkt, wird Eure Gesundheit wieder auf 30% erhöht und Euer gesamter erlittener Schaden 10 Sek. lang um 50% verringert.\n\nDieser Effekt kann nur ein Mal alle 90 Sek. auftreten." }
entries[108415] = { ["name"] = "Seelenverbindung", ["text"] = "100 Meter Reichweite\n20% allen erlittenen Schadens werden mit Eurem beschworenen Dämonen geteilt. Zusätzlich werden 3% allen verursachten Schadens in Heilung für Euch und Euren beschworenen Dämonen umgewandelt." }
entries[108416] = { ["name"] = "Opferpakt", ["text"] = "100 Meter Reichweite\nSofort 1 min Abklingzeit\nEuer Dämon opfert 25% seiner aktuellen Gesundheit, um seinen Meister in einen Schild zu hüllen, der Schaden in Höhe von 400% der geopferten Gesundheit absorbiert. Hält 20 Sek. lang an.\n\nWenn Ihr zu diesem Zeitpunkt nicht über einen Dämon verfügt, wird stattdessen Eure Gesundheit geopfert. Kann gewirkt werden, während Ihr von kontrolleinschränkenden Effekten betroffen seid. [ Kodex von Xerrath : \"Lasst einen anderen den Preis Eurer Tollkühnheit zahlen.\" -Zelfrax ]" }
entries[108419] = { ["name"] = "Magensäure", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt einem feindlichen Ziel 30625 bis 39375 Naturschaden zu." }
