entries[108499] = { ["name"] = "Grimoire der Überlegenheit", ["text"] = "Ihr habt Gewalt über stärkere Dämonen, die Eure gewöhnlichen Dämonen ersetzen. Diese Dämonen verursachen zusätzlich 20% Schaden und haben machtvollere Fähigkeiten.\n\nErlernte Zauber:\nTeufelswichtel beschwören\nLeerenfürsten beschwören\nShivarra beschwören\nErzinkubus beschwören\nBeobachter beschwören [ Dämonologie : Zornwächter beschwören ] Abyssal beschwören\nTerrorwache beschwören" }
