entries[108501] = { ["name"] = "Grimoire der Dienstbarkeit", ["text"] = "Sofort 2 min Abklingzeit\nBeschwört sofort einen zweiten Dämon, der Euch 20 Sek. lang im Kampf unterstützt. Der Dämon wird sofort eine seiner Spezialfähigkeiten nutzen:\n\nGrimoire: Wichtel : Entfernt sofort nach der Beschwörung einen schädlichen magischen Effekt vom Meister.\nGrimoire: Leerwandler Verspottet das Ziel sofort nach der Beschwörung.\nGrimoire: Sukkubus Ist das Ziel humanoid, wird es sofort verführt.\nGrimoire: Inkubus Ist das Ziel humanoid, wird es sofort verführt.\nGrimoire: Teufelsjäger Unterbricht das Ziel sofort nach der Beschwörung. [ Dämonologie : Grimoire: Teufelswache Betäubt das Ziel sofort nach der Beschwörung ]" }
entries[108502] = { ["name"] = "Teleport to PTR Encounter" }
entries[108503] = { ["name"] = "Grimoire der Opferung", ["text"] = "Unbegrenzte Reichweite\nSofort 30 sek. Abklingzeit\nOpfert Euren Dämon, um Euch eine seiner Fähigkeiten zueigen zu machen, die Macht vieler Eurer Einzelzielschadenszauber um [ Gebrechen : 20 ] [ Dämonologie : 25 ] [ Zerstörung : 15 ]% [ Seelenverbindung : sowie Eure maximale Gesundheit um 20% ]zu erhöhen und alle 5 Sek. 2% Eurer maximalen Gesundheit zu regenerieren. Hält 1 Stunde lang an.\n\nDurch das Beschwören eines neuen Dämons wird der Effekt beendet." }
