entries[108559] = { ["name"] = "Dämonische Wiedergeburt", ["text"] = "Stirbt Euer beschworener Dämon, erhaltet Ihr den Effekt 'Dämonische Wiedergeburt', durch den die Zauberzeit Eures nächsten Wirkens von 'Dämon beschwören' um 100% verringert wird.\n\nHält 20 Sek. lang an.\nDieser Effekt hat eine Abklingzeit von 2 Min." }
entries[108560] = { ["name"] = "Dämonische Freiheit", ["text"] = "Unbegrenzte Reichweite\nSofort 1.5 min Abklingzeit\nEuer Dämon gewinnt sofort 25% seiner maximalen Gesundheit und wird von allen auf ihn wirkenden Betäubungs-, Verlangsamungs-, Verbannungs-, Schreckens- und Furchteffekten sowie bewegungseinschränkenden Effekten befreit. Zudem wird er 15 Sek. lang gegen diese Effekte immun." }
