entries[108683] = { ["name"] = "Feuer und Schwefel", ["text"] = "Sofort 1 sek. Abklingzeit\nEuer nächstes Wirken von 'Feuerbrand', 'Verbrennen', 'Feuersbrunst' oder einem Eurer Flüche kostet einen instabilen Funken und trifft alle Gegner im Umkreis von 10 Meter um Euer Ziel und der Zauber verursacht jeweils [(35 * (100 + 24 * (( 90 > 79 ? 1 : 0))) / 100)]% seines normalen Schadens." }
entries[108685] = { ["name"] = "Feuersbrunst", ["text"] = "1 Combopunkt 40 Meter Reichweite\nSpontanzauber 12 sek. Wiederaufladung\n2 Aufladungen\nDer Gegner explodiert sofort und fügt allen Gegnern im Umkreis von 10 Metern [Quellwert]) Feuerschaden zu [ Glyphe 'Feuersbrunst' : Verringert außerdem ihr Bewegungstempo 5 Sek. lang um 30% / .\n\nWenn 'Feuerbrand' auf dem Ziel aktiv ist, wird sein Bewegungstempo 5 Sek. lang um 30% verringert.]\nErzeugt instabile Funken. Kritische Treffer verdoppeln diesen Effekt.", ["unresolvedValues"] = true }
entries[108686] = { ["name"] = "Feuerbrand", ["text"] = "1 Combopunkt 40 Meter Reichweite\nWirken in 1.5 sek.\nVerbrennt alle Gegner im Umkreis von 10 Metern um das Ziel, fügt ihnen [Quellwert]) Feuerschaden zu sowie zusätzlich im Verlauf von 15 Sek. weitere [Quellwert]) Feuerschaden. [ Instabile Funken : Kritische Treffer erzeugen instabile Funken ]", ["unresolvedValues"] = true }
